var manage_default = "---\nlayout: article\ntitle: Manage organizations\ndescription: Create and update Appwrite organizations from your partner platform using the Console Organization API.\n---\n\nUse the Organization API to provision and configure organizations as part of your onboarding flow.\n\n# Create an organization {% #create-an-organization %}\n\n{% multicode %}\n```server-nodejs\nimport { Client, Organizations } from 'node-appwrite';\n\nconst client = new Client()\n    .setEndpoint('https://cloud.appwrite.io/v1')\n    .setProject('console')\n    .setKey(process.env.APPWRITE_ORG_API_KEY);\n\nconst organizations = new Organizations(client);\n\nconst org = await organizations.create({\n    organizationId: 'unique()',\n    name: 'Acme Platform Customer',\n    billingEmail: 'billing@example.com',\n});\n```\n{% /multicode %}\n\nStore the returned organization ID in your platform database and associate it with the customer record.\n\n# Update organization settings {% #update-organization-settings %}\n\nUpdate name, billing email, and preferences when customers change settings in your product:\n\n{% multicode %}\n```server-nodejs\nawait organizations.update({\n    organizationId: orgId,\n    name: 'Updated name',\n});\n```\n{% /multicode %}\n\n# Map organizations to customers {% #map-organizations-to-customers %}\n\nMaintain a stable mapping between your customer ID and Appwrite `organizationId`. Use this mapping for all Console API calls and audit logs.\n\n# Related {% #related %}\n\n{% arrow_link href=\"/docs/partners/projects/create\" %}\nCreate projects\n{% /arrow_link %}\n";
